import { describe, expect, it } from "vitest";
import recorded from "./__fixtures__/recap-game.json" with { type: "json" };
import type { Context, GameEvent } from "./describe-event";
import { affects, buildRecap } from "./recap";
import type { HistoryEntry, View } from "./types";

/**
 * A recorded reconnect: Ana (p1) plays with three bots and comes back after greedy bot 4's
 * Wild Rent on her. Generated by playing a seeded room (packages/room test-setup) to that point.
 */
const view = recorded.view as unknown as View;
const history = recorded.history as unknown as HistoryEntry[];
const ctx: Context = {
  viewer: "p1",
  playerName: (id) => recorded.lobby.seats.find((s) => s.player === id)?.name ?? id,
  card: (id) => view.cards[id],
  districtName: (id) => view.districts[id]?.name ?? id,
};

describe("recap of a recorded game (#41)", () => {
  const recap = buildRecap(history, ctx, view);

  it("shows exactly the events since the player's last move, in order", () => {
    expect(recap.groups.flatMap((g) => g.items.map((i) => i.seq))).toEqual(
      history.map((e) => e.seq),
    );
  });

  it("groups them by player turn, starting a group at each turn", () => {
    expect(recap.groups.map((g) => [g.turn, g.player && ctx.playerName(g.player)])).toEqual([
      [2, "greedy bot 2"],
      [3, "random bot 3"],
      [4, "greedy bot 4"],
    ]);
    // the play that ended greedy bot 2's turn stays in that turn, though it was logged as turn 3
    expect(recap.groups[0]?.items.at(-1)?.text).toMatch(/^Greedy bot 2 banked/);
  });

  it("marks what affected the player: the rent and its outcome", () => {
    const marked = recap.groups.flatMap((g) =>
      g.items.filter((i) => i.affected).map((i) => i.text),
    );
    expect(marked).toEqual([
      "Greedy bot 4 charged $3 rent on RTP to you",
      "Auto-pass answered for you (no Appeal in hand)",
      "Greedy bot 4's Wild Rent stands: you owe $3",
    ]);
  });

  it("sums it up on one line", () => {
    expect(recap.summary).toBe(
      "3 turns since you played · random bot 3 now has 1 of 3 complete districts",
    );
  });
});

const entry = (seq: number, event: GameEvent, turn = 7): HistoryEntry => ({
  seq,
  turn,
  round: 2,
  seat: 1,
  event,
});
const card = (name: string, value: number) => ({
  kind: "cash" as const,
  id: name,
  name,
  value,
  count: 1,
});
const small: Context = {
  viewer: "me",
  playerName: (id) => ({ me: "Ana", sam: "Sam", alex: "Alex" })[id] ?? id,
  card: (id) => ({ c2: card("$2", 2), c5: card("$5", 5), erwin: card("Erwin Rd", 4) })[id],
  districtName: (id) => id.toUpperCase(),
};
const set = (district: string, n: number) => ({
  district,
  cards: Array.from({ length: n }, (_, i) => `${district}-${i}`),
});
const smallView = {
  turn: 9,
  currentPlayer: "me",
  rules: { districtsToWin: 3 },
  districts: { duke: { setSize: 2 }, rtp: { setSize: 2 } },
  cards: Object.fromEntries(
    ["duke-0", "duke-1", "rtp-0", "rtp-1"].map((c) => [c, { kind: "property" }]),
  ),
  players: [
    // seat (and turn) order: me, sam, alex
    { id: "me", tableau: [] },
    { id: "sam", tableau: [set("duke", 1)] },
    { id: "alex", tableau: [set("duke", 2), set("rtp", 2)] },
  ],
} as unknown as View;

describe("what affected you (#41)", () => {
  it("steals: a Buyout, Swap Meet or Hostile Takeover on you, and the summary names the loss", () => {
    const steal = (kind: "buyout" | "swap" | "takeover"): GameEvent => ({
      type: "actionResolved",
      attacker: "sam",
      target: "me",
      card: "a",
      cancelled: false,
      effect:
        kind === "takeover"
          ? { kind, district: "duke" }
          : kind === "swap"
            ? { kind, take: "erwin", give: "c2" }
            : { kind, take: "erwin" },
    });
    for (const kind of ["buyout", "swap", "takeover"] as const)
      expect(affects(steal(kind), "me")).toBe(true);
    expect(affects(steal("buyout"), "alex")).toBe(false);
    const recap = buildRecap(
      [entry(1, steal("buyout")), entry(2, steal("takeover"))],
      small,
      smallView,
    );
    expect(recap.summary).toContain("you lost Erwin Rd, your DUKE set");
  });

  it("payments: paid by you or to you, and a debt forgiven", () => {
    const paid = (debtor: string, creditor: string): GameEvent => ({
      type: "paid",
      debtor,
      creditor,
      cards: ["c2", "c5"],
    });
    expect(affects(paid("me", "sam"), "me")).toBe(true);
    expect(affects(paid("sam", "me"), "me")).toBe(true);
    expect(affects(paid("sam", "alex"), "me")).toBe(false);
    expect(affects({ type: "debtSettled", debtor: "me", creditor: "sam", forgiven: 2 }, "me")).toBe(
      true,
    );
    const recap = buildRecap(
      [entry(1, paid("me", "sam")), entry(2, paid("alex", "me"))],
      small,
      smallView,
    );
    expect(recap.summary).toContain("you lost $2, $5 · you received $7");
  });

  it("rent charged to you", () => {
    const rent: GameEvent = {
      type: "rentCharged",
      player: "sam",
      card: "r",
      district: "duke",
      amount: 2,
      debtors: ["me", "alex"],
    };
    expect(affects(rent, "me")).toBe(true);
    expect(affects({ ...rent, debtors: ["alex"] }, "me")).toBe(false);
  });

  it("a Construction Delay on you", () => {
    const delay: GameEvent = {
      type: "actionResolved",
      attacker: "sam",
      target: "me",
      card: "d",
      cancelled: false,
      effect: { kind: "delay" },
    };
    expect(affects(delay, "me")).toBe(true);
    expect(affects({ type: "actionPlayed", player: "sam", card: "d", target: "me" }, "me")).toBe(
      true,
    );
  });

  it("Appeals against you, but not Appeals in chains you weren't part of", () => {
    const chain = (attacker: string, target: string) => [
      entry(1, { type: "actionPlayed", player: attacker, card: "d", target }),
      entry(2, { type: "responded", player: target, appeal: true }),
      entry(3, { type: "responded", player: attacker, appeal: false }),
      entry(4, {
        type: "actionResolved",
        attacker,
        target,
        card: "d",
        cancelled: true,
        effect: { kind: "delay" },
      }),
    ];
    const flagged = (entries: HistoryEntry[]) =>
      buildRecap(entries, small, smallView).groups[0]?.items.map((i) => i.affected);
    // Sam appealed my action: every step concerns me
    expect(flagged(chain("me", "sam"))).toEqual([false, true, false, true]);
    // Alex appealed Sam's action: none of it concerns me
    expect(flagged(chain("sam", "alex"))).toEqual([false, false, false, false]);
  });

  it("groups by turn and leads with the turn count and the leaders", () => {
    const recap = buildRecap(
      [
        entry(1, { type: "banked", player: "sam", card: "c2" }, 7),
        entry(2, { type: "turnStarted", player: "alex", turn: 8, round: 2 }, 8),
        entry(3, { type: "turnStarted", player: "me", turn: 9, round: 3 }, 9),
      ],
      small,
      smallView,
    );
    expect(recap.groups.map((g) => [g.turn, g.player])).toEqual([
      [7, "sam"],
      [8, "alex"],
      [9, "me"],
    ]);
    expect(recap.summary).toBe("2 turns since you played · Alex now has 2 of 3 complete districts");
  });
});
